	@ParameterizedTest
	@EnumSource(value = Mode.class, names = { "CRASH_OUTGOING", "CRASH_BOTH_COMMITS", "CRASH_ACKNOWLEDGED" })
	@Timeout(120)
	void certifiedInitialImportCrashNeverPublishesOnlyOneDirection(Mode mode) throws Exception {
		Path data = directory.resolve("store");
		Path witnessFile = directory.resolve("cut.witness");
		Path output = directory.resolve("child.log");
		String java = Path.of(System.getProperty("java.home"), "bin", "java").toString();
		String agent = "-javaagent:"
				+ Path.of(Mockito.class.getProtectionDomain().getCodeSource().getLocation().toURI());
		Process child = new ProcessBuilder(java, "-ea", "-Xmx384m", "-XX:ActiveProcessorCount=2",
				"-XX:-CreateCoredumpOnCrash", "-XX:ErrorFile=" + directory.resolve("hs_err_pid%p.log"),
				"--enable-native-access=ALL-UNNAMED", agent,
				"-cp", System.getProperty("java.class.path"), CrashChild.class.getName(), data.toString(), mode.name(),
				witnessFile.toString()).redirectErrorStream(true).redirectOutput(output.toFile()).start();
		try {
			assertTrue(child.waitFor(90, TimeUnit.SECONDS), "owned child must reach its actual cut: " + output);
			String evidence = Files.readString(output);
			assertEquals(CHILD_EXIT, child.exitValue(), evidence);
			assertThat(evidence).contains("CERTIFIED_INITIAL_DIRECT_CUT=" + mode);
		} finally {
			if (child.isAlive()) {
				child.destroyForcibly();
				assertTrue(child.waitFor(10, TimeUnit.SECONDS), "reap only this test's child");
			}
		}
		Witness witness = readWitness(witnessFile);
		assertThat(witness.mode()).isEqualTo(mode);
		assertThat(witness.lastWriter()).isNotZero();
		assertThat(witness.environment()).isNotZero();
		assertThat(witness.outgoingPages()).isGreaterThanOrEqualTo(2);
		assertThat(witness.authorityHash()).matches("[0-9a-f]{64}");
		assertThat(witness.marker()).isEqualTo(mode != Mode.CRASH_ACKNOWLEDGED);
		if (mode == Mode.CRASH_OUTGOING) {
			assertThat(witness.activeWriter()).isNotZero();
			assertThat(witness.incomingPages()).isZero();
			assertThat(witness.dictionaryCommits()).isZero();
			assertThat(witness.tripleCommits()).isZero();
		} else {
			assertThat(witness.activeWriter()).isZero();
			assertThat(witness.incomingPages()).isGreaterThanOrEqualTo(2);
			assertThat(witness.dictionaryCommits()).isEqualTo(1);
			assertThat(witness.tripleCommits()).isEqualTo(1);
		}
		assertThat(witness.completedImports()).isEqualTo(mode == Mode.CRASH_ACKNOWLEDGED ? 1 : 0);
		assertReopened(data, witness.ids(), mode == Mode.CRASH_ACKNOWLEDGED);
	}

	private static Observation runImport(Path data, Mode mode, Path witness) throws Exception {
		long previousChunkBytes = LmdbInitialRunImport.chunkBytesForTest;
		LmdbInitialRunImport.chunkBytesForTest = 16L << 10;
		Observation observation = new Observation(data, mode, witness);
		ObservedStore sail = new ObservedStore(data.toFile(), observation);
		try {
			sail.init();
			LmdbSailStore backing = sail.getBackingStore();
			observation.backing = backing;
			Set<Statement> fixture = fixture(sail.getValueFactory());
			assertThat(fixture).hasSize(DISTINCT_ROWS);
			try (LmdbStoreConnection writer = (LmdbStoreConnection) sail.getConnection()) {
				writer.begin(IsolationLevels.NONE);
				for (int repeat = 0; repeat < 2; repeat++) {
					int rows = 0;
					for (Statement statement : fixture) {
						writer.addStatement(statement.getSubject(), statement.getPredicate(), statement.getObject(),
								statement.getContext());
						if (++rows % 256 == 0) {
							backing.flushNonePending(writer, false);
						}
					}
					backing.flushNonePending(writer, false);
				}
				assertThat(backing.isInitialRunImportActive()).isTrue();
				assertThat(data.resolve(LmdbInitialRunImport.MARKER_FILE_NAME)).exists();
				observation.ids = dictionaryIds((ObservedValues) backing.valueStore(), fixture);
				observation.expected = numeric(fixture, observation.ids);
				observation.dictionaryGenerationBefore = backing.valueStore().nativeCommitGeneration();
				observation.armed = true;
				backing.beforeAsyncOperationForTest = observation::openWorkerScope;
				backing.afterAsyncTransactionForTest = observation::closeWorkerScope;
				backing.afterAsyncFailureForTest = ignored -> observation.closeWorkerScope();
				Throwable failure = catchThrowable(writer::commit);
				if (mode == Mode.INCOMING_NON_CAPACITY) {
					assertThat(failure).as("actual native corruption return is terminal").isNotNull();
					assertThat(failure).hasStackTraceContaining("MDB_CORRUPTED");
					assertThat(backing.initialRunImportsCompleted()).isZero();
					assertThat(data.resolve(LmdbInitialRunImport.MARKER_FILE_NAME)).exists();
					assertThat(catchThrowable(() -> {
						try (var peer = sail.getConnection()) {
							peer.size();
						}
					})).as("failed initial import refuses new peer reads until reset").isNotNull();
				} else {
					assertThat(failure).as("capacity replay preserves the public commit").isNull();
					assertThat(backing.initialRunImportsCompleted()).isEqualTo(1);
					assertThat(data.resolve(LmdbInitialRunImport.MARKER_FILE_NAME)).doesNotExist();
					assertThat(data.resolve(LmdbInitialRunImport.RUN_DIRECTORY_NAME)).doesNotExist();
					assertCommitted(sail, observation.expected, observation.ids, true);
					assertFanOut(observation.triples, observation.expected);
					if (mode == Mode.CRASH_ACKNOWLEDGED) {
						observation.certifyAndHalt();
					}
				}
			}
		} finally {
			try {
				sail.shutDown();
			} finally {
				LmdbInitialRunImport.chunkBytesForTest = previousChunkBytes;
			}
		}
		assertThat(observation.activeScopes.get()).as("native owner closes every thread-local observer").isZero();
		return observation;
	}

	private static Set<Statement> fixture(ValueFactory vf) {
		IRI[] nodes = new IRI[32];
		for (int i = 0; i < nodes.length; i++) {
			nodes[i] = vf.createIRI("urn:direct-recovery:n" + i);
		}
		Set<Statement> result = new LinkedHashSet<>();
		for (int p = 0; p < 2; p++) {
			for (IRI subject : nodes) {
				for (IRI object : nodes) {
					result.add(vf.createStatement(subject, nodes[p], object));
					result.add(vf.createStatement(subject, nodes[p], object, nodes[0]));
				}
			}
		}
		for (int i = 0; i < 17; i++) {
			result.add(vf.createStatement(nodes[i], nodes[2], nodes[31], nodes[0]));
		}
		return result;
	}

	private static Map<String, Long> dictionaryIds(ObservedValues values, Set<Statement> fixture) throws IOException {
		Set<String> expectedValues = new HashSet<>();
		for (Statement statement : fixture) {
			for (var value : List.of(statement.getSubject(), statement.getPredicate(), statement.getObject())) {
				expectedValues.add(value.stringValue());
			}
			if (statement.getContext() != null) {
				expectedValues.add(statement.getContext().stringValue());
			}
		}
		assertThat(expectedValues).hasSize(32);
		assertThat(values.assignmentCalls).as("actual production fresh assignment was observed").isPositive();
		Map<String, Long> ids = values.assignedIds;
		assertThat(ids.keySet()).isEqualTo(expectedValues);
		assertThat(ids).hasSize(32);
		assertThat(ids.values()).allSatisfy(id -> assertThat(id).isPositive());
		for (Map.Entry<String, Long> entry : ids.entrySet()) {
			// Forward resolution can be cache-backed. Persisted reverse identity is proved only after commit/reopen.
			assertThat(values.getValue(entry.getValue())).as("assigned identity resolves to its exact RDF IRI")
					.isEqualTo(SimpleValueFactory.getInstance().createIRI(entry.getKey()));
		}
		return Map.copyOf(ids);
	}

	private static Set<Quad> numeric(Set<Statement> fixture, Map<String, Long> ids) {
		Set<Quad> result = new HashSet<>();
		for (Statement statement : fixture) {
			assertTrue(result.add(new Quad(ids.get(statement.getSubject().stringValue()),
					ids.get(statement.getPredicate().stringValue()), ids.get(statement.getObject().stringValue()),
					statement.getContext() == null ? 0 : ids.get(statement.getContext().stringValue()), true)));
		}
		return result;
	}

	private static void assertReopened(Path data, Map<String, Long> ids, boolean acknowledged) throws Exception {
		Set<Quad> original = numeric(fixture(SimpleValueFactory.getInstance()), ids);
		for (int reopen = 0; reopen < 2; reopen++) {
			LmdbStore sail = new LmdbStore(data.toFile(), config());
			try {
				sail.init();
				assertCommitted(sail, acknowledged ? original : Set.of(), ids, acknowledged);
				assertThat(data.resolve(LmdbInitialRunImport.MARKER_FILE_NAME)).doesNotExist();
				assertThat(data.resolve(LmdbInitialRunImport.RUN_DIRECTORY_NAME)).doesNotExist();
			} finally {
				sail.shutDown();
			}
		}
	}

	private static void assertCommitted(LmdbStore sail, Set<Quad> expected, Map<String, Long> ids, boolean acknowledged)
			throws IOException {
		Set<Statement> rdf = fixture(SimpleValueFactory.getInstance());
		Set<Quad> universe = numeric(rdf, ids);
		TripleStore triples = sail.getBackingStore().getTripleStore();
		triples.getTxnManager().doWith((stack, txn) -> {
			assertCompleteAuthority(txn, expected, universe);
			return null;
		});
		ValueStore values = sail.getBackingStore().valueStore();
		for (Map.Entry<String, Long> entry : ids.entrySet()) {
			IRI value = SimpleValueFactory.getInstance().createIRI(entry.getKey());
			assertThat(values.getId(value)).as("original assigned dictionary ID for %s", value)
					.isEqualTo(acknowledged ? entry.getValue() : -1L);
			if (acknowledged) {
				assertThat(values.getValue(entry.getValue())).isEqualTo(value);
			}
		}
		try (var reader = sail.getConnection(); var rows = reader.getStatements(null, null, null, false)) {
			List<? extends Statement> actual = rows.stream().toList();
			assertThat(actual).hasSize(expected.size());
			assertThat(new HashSet<>(actual)).isEqualTo(acknowledged ? rdf : Set.of());
			assertThat(reader.size()).isEqualTo(expected.size());
		}
	}

	private static void assertCompleteAuthority(long txn, Set<Quad> expected, Set<Quad> universe) throws IOException {
		LmdbPersistentAdjacencyContractAssertions.assertSnapshot(txn, expected, universe);
		LmdbPersistentAdjacency adjacency = LmdbPersistentAdjacency.openExisting(txn);
		assertThat(records(txn, adjacency.deltasDbi())).isEmpty();
		assertThat(records(txn, adjacency.metadataDbi()).keySet()).allSatisfy(key -> {
			int type = Byte.toUnsignedInt(HexFormat.of().parseHex(key)[0]);
			assertThat(type).as("no disposable dirty or compaction candidate authority").isBetween(0, 7);
		});
		if (expected.isEmpty()) {
			assertThat(records(txn, adjacency.pagesDbi())).isEmpty();
			assertThat(records(txn, adjacency.metadataDbi())).hasSize(1).containsKey("00");
		}
	}

	private static void assertFanOut(TripleStore triples, Set<Quad> model) {
		LmdbFanOutStats expected = new LmdbFanOutStats();
		Set<Long> predicates = new HashSet<>();
		for (Quad quad : model) {
			expected.recordAdded(quad.subject(), quad.predicate(), quad.object());
			predicates.add(quad.predicate());
		}
		for (long predicate : predicates) {
			for (boolean bySubject : new boolean[] { true, false }) {
				assertThat(triples.meanFanOut(predicate, bySubject, true))
						.isEqualTo(expected.meanFanOut(predicate, bySubject));
				assertThat(triples.distinctFanOutKeys(predicate, bySubject, true))
						.isEqualTo(expected.distinctKeys(predicate, bySubject));
				assertThat(triples.meanFanOut(predicate, bySubject, false)).isEmpty();
			}
		}
	}

